export const practiceDifficulties=["easy","standard","hard"],parseDifficulty=(t)=>practiceDifficulties.some((o)=>o===t)?t:"standard",practiceSlot=(t)=>t==="standard"?"practice":`practice:${t}`;export function practiceSettings(t,o){const i=document.createElement("div");i.className="practice-settings";i.hidden=!0;const s=document.createElement("div");s.className="practice-settings-row";const r=document.createElement("label");r.htmlFor="practice-difficulty";r.textContent="Difficulty";const e=document.createElement("select");e.id=r.htmlFor;e.setAttribute("aria-describedby","practice-difficulty-description");for(const c of practiceDifficulties){const n=document.createElement("option");n.value=c;n.textContent=c[0].toUpperCase()+c.slice(1);e.append(n)}const a=document.createElement("p");a.id="practice-difficulty-description";a.setAttribute("role","status");s.append(r,e);i.append(s,a);e.onchange=()=>o(parseDifficulty(e.value));return{element:i,sync(c,n){i.hidden=!n;e.value=c;a.textContent=t[c]}}}